    for (let n = 2; primes.length < 6; n += 1) if (isPrime(n)) primes.push(n) // first 6 primes, computed
    const eulerPartial = roundTo(primes.reduce((acc, p) => acc * (p * p) / (p * p - 1), 1), 5) // → ζ(2)
